@startuml

class User {
  + UserID : int
  + Name : string
  + Email : string
  + DateOfBirth : date
}

class Account {
  + AccountNumber : int
}

class PersonalAccount {
}

class BusinessAccount {
  + CompanyName : string
  + MonthlyFee : double
}

class Page {
  + PageName : string
  + NumberOfVisits : int
}

class AdvertisementPage {
  + BounceRate : float
  + ClickThroughRate : float
  + ConversionRate : float
}

class FriendRequest {
}

User "1" -- "1" Account
Account --|> PersonalAccount
Account --|> BusinessAccount
PersonalAccount --|> Account
BusinessAccount --|> Account

Account "1" -- "*" Page
PersonalAccount "1" -- "*" FriendRequest
FriendRequest "*" -- "1" PersonalAccount : sender
FriendRequest "*" -- "1" PersonalAccount : receiver

Account "1" -- "*" Page : creates
PersonalAccount "0..*" -- "*" Page : privileges

Page --|> AdvertisementPage
BusinessAccount "1" -- "*" AdvertisementPage : creates

@enduml

